const { PDFDocument } = require('pdf-lib');
const fontkit = require('@pdf-lib/fontkit');
const fs = require('fs');

(async () => {
  const doc = await PDFDocument.create();
  doc.registerFontkit(fontkit);
  const fontBytes = fs.readFileSync('/usr/share/fonts/workspacex/NotoSansSC-Common.otf');
  const font = await doc.embedFont(fontBytes);

  const pageW = 595;
  const pageH = 842;
  const marginL = 50;
  const marginR = 50;
  const usableW = pageW - marginL - marginR;

  const titleSize = 26;
  const h1Size = 16;
  const bodySize = 11;
  const lineH = 17;

  function wrap(text, size) {
    const maxChars = Math.floor(usableW / size);
    const lines = [];
    let cur = '';
    for (const ch of text) {
      if (cur.length >= maxChars) {
        lines.push(cur);
        cur = ch;
      } else {
        cur += ch;
      }
    }
    if (cur) lines.push(cur);
    return lines;
  }

  const sections = [
    {
      title: '文档与文件处理',
      items: [
        '创建和编辑 Word (.docx)、Excel (.xlsx)、PowerPoint (.pptx)、PDF 文件',
        '读取并理解上传的 Office、PDF、CSV 内容，提取表格与关键信息',
        '填写标准 PDF AcroForm 表单字段（文本框、复选框）',
        '数据分析：清洗、统计、可视化图表生成',
      ],
    },
    {
      title: '会议与沟通',
      items: [
        '音频转写：将录音转为带时间戳的可审阅文本',
        '会议纪要：从转录中提炼决策、行动项及证据位置',
        '会议准备：整理背景材料、议程与预读清单',
        '访谈综合：跨多场访谈归纳主题、引文与反例',
        '用户研究规划：制定研究计划、招募条件与中立提纲',
        '内部沟通稿：公告、领导更新、FAQ、3P 周报草稿',
        '项目状态报告：基于授权资料生成周报或里程碑简报',
      ],
    },
    {
      title: '知识与研究',
      items: [
        '知识问答：基于组织资料给出有出处的回答',
        '网络研究：联网查证、比较方案并保留引用与冲突',
        '技能编写：把重复流程整理成可导入的技能草稿包',
      ],
    },
    {
      title: '视觉与交互产物',
      items: [
        '海报/配图：确定构图文案，生成图片或精确排版',
        '画布与图表：Mermaid / fabric 画布、MAAU Canvas',
        'Web 产物：自包含交互式网页，交付前浏览器验收',
      ],
    },
    {
      title: '系统与工具',
      items: [
        '文件读写、目录浏览、Shell 命令执行',
        '任务拆解与进度跟踪（To-Do 管理）',
        '参数确认、意图澄清、方案选择等协作流程',
        '产物发布：将工作区文件以指定媒体类型交付',
      ],
    },
  ];

  // --- Page 1 ---
  let page = doc.addPage([pageW, pageH]);
  let y = pageH - 60;

  const titleLines = wrap('我可以做的事情 · 能力总结', titleSize);
  for (const ln of titleLines) {
    page.drawText(ln, { x: marginL, y, size: titleSize, font });
    y -= titleSize + 8;
  }
  y -= 10;

  // Subtitle / intro
  const intro = '以下是当前可用技能与工具的概览。每项能力均可在对话中按需调用，产出可核验的文件或结论。';
  const introLines = wrap(intro, bodySize);
  for (const ln of introLines) {
    page.drawText(ln, { x: marginL, y, size: bodySize, font });
    y -= lineH;
  }
  y -= 18;

  function ensureSpace(needed) {
    if (y - needed < 60) {
      page = doc.addPage([pageW, pageH]);
      y = pageH - 60;
    }
  }

  for (const sec of sections) {
    const sectionBlockH = (h1Size + 8) + sec.items.length * lineH + 14;
    ensureSpace(sectionBlockH);

    // Section title underline
    page.drawText(sec.title, { x: marginL, y, size: h1Size, font });
    page.drawLine({
      start: { x: marginL, y: y - 4 },
      end: { x: marginL + usableW, y: y - 4 },
      thickness: 0.8,
    });
    y -= h1Size + 10;

    for (const item of sec.items) {
      const itemLines = wrap('• ' + item, bodySize);
      ensureSpace(itemLines.length * lineH);
      for (const ln of itemLines) {
        page.drawText(ln, { x: marginL + 8, y, size: bodySize, font });
        y -= lineH;
      }
    }
    y -= 14;
  }

  // Footer note on last page
  ensureSpace(lineH * 2);
  y -= 10;
  const footer = '注：以上能力依赖当前沙箱环境与已授权技能；具体输出以实际执行为准。';
  const footerLines = wrap(footer, 9);
  for (const ln of footerLines) {
    page.drawText(ln, { x: marginL, y, size: 9, font, color: { r: 0.4, g: 0.4, b: 0.4 } });
    y -= 14;
  }

  const bytes = await doc.save();
  fs.writeFileSync('/workspace/capabilities-summary.pdf', bytes);
  console.log('OK');
})().catch((e) => { console.error(e.stack); process.exit(1); });
